# SPDX-License-Identifier: Apache-2.0
import json,csv
from pathlib import Path
root=Path('results/pcm24-routing');s=json.loads((root/'summary.json').read_text());rows=json.loads((root/'cpu.json').read_text());blocks=json.loads((root/'browser-blocks.json').read_text())
assert len(rows)==18 and all(r['accepted'] for r in rows)
assert all(v['accepted']==3 for v in s.values())
assert not any(b['status']=='failed' for b in blocks)
lines=['## Measured results','', 'All 18 windows accepted; three rounds per arm. Values are median percent of one CPU core. Role medians are calculated independently. Whole Chrome includes browser and other utility processes as well as the displayed roles.','', '| Arm | Whole Chrome | Renderer | GPU | Audio service | Whole range | Saving vs Hybrid |','|---|---:|---:|---:|---:|---:|---:|']
for arm,v in s.items():
    roles=v['roles'];lines.append(f"| {arm} | {v['whole']:.2f} | {roles['renderer']:.2f} | {roles['gpu']:.2f} | {roles['audio']:.2f} | {v['range'][0]:.2f}–{v['range'][1]:.2f} | {v['savingVsHybrid']:.2f} |")
lines+=['',f"Hybrid → direct saves **{s['direct']['savingVsHybrid']:.2f} core points**; Hybrid → existing FLAC saves **{s['flac']['savingVsHybrid']:.2f}**. Both exceed 10 points in every corresponding round. This is a **routing/qualification problem for this bounded fixture**, with native-direct MKV the cheapest correct measured route. The selective PCM experiment saves **{s['selective']['savingVsHybrid']:.2f} points**, so **it does not meet the requested 10-point threshold**. Video can stay browser-owned, but retaining a separate mpv audio service does not capture most of the available saving here.",'',f"Suppressing Hybrid drawing removes **{s['hybrid-no-draw']['savingVsHybrid']:.2f} points**; disabling its selected audio removes **{s['hybrid-no-audio']['savingVsHybrid']:.2f} points**. The drawing delta includes renderer/GPU presentation work while retained-frame scheduling and decode remain active. The audio-off control retains the silent output service. Thus the dominant measured removable cost is presentation, not PCM decoding alone.",'',f"Selective CPU-window sync: absolute error p50 **{s['selective']['syncMs']['p50']:.2f} ms**, p95 **{s['selective']['syncMs']['p95']:.2f} ms**, maximum **{s['selective']['syncMs']['max']:.2f} ms**; **zero pre-EOF underruns**, zero mpv video tracks. Hybrid and no-draw windows also have zero measured underrun increments. Audio-off publishes zero media frames.",'','The fresh Hybrid median differs from the historical 27.5% number; no causal delta is calculated across those campaigns. Native/FLAC variance is retained in the table rather than hidden. Whole-Chrome CPU excludes the fixture server, OS WindowServer/CoreAudio/media services and GPU energy.','']
p=root/'REPORT.md';body=p.read_text().replace('Status: correctness and digital audio checks complete; matched CPU campaign running. Production source and routing unchanged.','**Finding: routing/qualification problem for this bounded fixture.** Native direct and existing FLAC clear the 10-core-point saving threshold with lossless audio and lifecycle checks; the separate-mpv-audio variant does not. Production source and routing unchanged.')
body=body.replace('## Why Auto rejects cheaper routes','\n'.join(lines)+'\n## Why Auto rejects cheaper routes');p.write_text(body)
with (root/'cpu-summary.csv').open('w') as f:
    w=csv.writer(f);w.writerow(['arm','round','whole','browser','renderer','gpu','audioService','accepted'])
    for r in rows:w.writerow([r['arm'],r['round'],r['cpu']['oneCorePercent'],*[r['cpu']['roles'][k] for k in ['browser','renderer','gpu','audio']],r['accepted']])
print('Report finalized; all 18 CPU windows accepted.')
